  mnemonic:{word:"TDKPSV", items:[["T","Tetanus: drumstick, spasm"],["D","Diphtheria: Chinese letters, membrane"],["K","Klebsiella: capsule, currant jelly"],["P","Pseudomonas: blue-green, burns"],["S","Salmonella: step-ladder fever"],["V","Vibrio: comma, rice-water"]], extra:"Think Toxins Destroy, Klebsiella Pseudomonas Spread in hospital, Water carries Salmonella and Vibrio."},
